import 'package:flutter/material.dart';
import 'package:koraone/core/i18n/app_strings.dart';
import 'package:koraone/core/network/auth_repository.dart';
class LoginScreen extends StatefulWidget{const LoginScreen({super.key});@override State<LoginScreen> createState()=>_LoginScreenState();}
class _LoginScreenState extends State<LoginScreen>{final login=TextEditingController(),password=TextEditingController();bool hide=true,busy=false;String? error;Future<void> submit()async{setState(()=>busy=true);try{await AuthRepository().login(login.text.trim(),password.text);if(mounted)Navigator.pop(context,true);}on DioException catch(e){setState(()=>error=e.response?.data?['message']?.toString()??'Login failed');}catch(_){setState(()=>error='Login failed');}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext context){final t=AppStrings.of(context);return Scaffold(appBar:AppBar(),body:SafeArea(child:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:440),child:ListView(padding:const EdgeInsets.all(24),children:[const Icon(Icons.sports_soccer,size:70),const SizedBox(height:18),Text(t('login'),style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.w900)),const SizedBox(height:24),TextField(controller:login,autofillHints:const [AutofillHints.username,AutofillHints.email],decoration:InputDecoration(labelText:t('email_user'),prefixIcon:const Icon(Icons.person_outline),border:const OutlineInputBorder())),const SizedBox(height:14),TextField(controller:password,obscureText:hide,autofillHints:const [AutofillHints.password],onSubmitted:(_)=>submit(),decoration:InputDecoration(labelText:t('password'),prefixIcon:const Icon(Icons.lock_outline),suffixIcon:IconButton(onPressed:()=>setState(()=>hide=!hide),icon:Icon(hide?Icons.visibility:Icons.visibility_off)),border:const OutlineInputBorder())),if(error!=null)Padding(padding:const EdgeInsets.only(top:12),child:Text(error!,style:TextStyle(color:Theme.of(context).colorScheme.error))),const SizedBox(height:18),FilledButton.icon(onPressed:busy?null:submit,icon:busy?const SizedBox.square(dimension:18,child:CircularProgressIndicator(strokeWidth:2)):const Icon(Icons.login),label:Padding(padding:const EdgeInsets.all(14),child:Text(t('login')))),TextButton(onPressed:(){},child:Text(t('register')))])))));}}
